from functools import lru_cache
class Solution:
    def countClassy(self, L: int, R: int) -> int:
        def f(x: int) -> int:
            if x <= 0:
                return 0
            s = str(x)
            @lru_cache(None)
            def dp(pos, nz, tight):
                if nz > 3:
                    return 0
                if pos == len(s):
                    return 1
                hi = int(s[pos]) if tight else 9
                res = 0
                for d in range(hi + 1):
                    res += dp(pos + 1, nz + (1 if d else 0), tight and d == hi)
                return res
            ans = dp(0, 0, True)
            dp.cache_clear()
            return ans
        return f(R) - f(L - 1)
